//! Durable creation intents. Only the vouched gateway can call this carrier;
//! its bounded jobs prepare folders and prove Store origins outside the actor.
//! Retrying an intent returns its recorded seed, never newly generated bytes.
use crate::{
    Database, Error,
    messages::Person,
    person::{self, Definition},
};
use rusqlite::{Connection, OptionalExtension, params};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

#[derive(Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AuthoredRole {
    pub title: String,
    pub markdown: String,
}

#[derive(Clone, Serialize, Deserialize)]
pub struct Seed {
    pub candidate: Uuid,
    pub request: Uuid,
    pub title: String,
    pub hash: String,
    pub bytes: Vec<u8>,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Phase {
    Intent,
    FolderPending,
    FolderReady,
    RolePending,
    Ready,
    Completed,
    Abandoned,
}
impl Phase {
    fn terminal(self) -> bool {
        matches!(self, Self::Completed | Self::Abandoned)
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Failure {
    FolderUnavailable,
    RoleUnavailable,
    RoleMissing,
    AuthorityUnavailable,
}

/// Includes private seed bytes; public projections must omit them. Debug is
/// deliberately redacted even though diagnostic enums themselves are safe.
#[derive(Clone, Serialize, Deserialize)]
pub struct Record {
    pub request: Uuid,
    pub bot: Uuid,
    pub revision: u64,
    pub definition: Definition,
    pub seed: Option<Seed>,
    pub phase: Phase,
    pub failure: Option<Failure>,
    pub folder_binding: Option<String>,
    pub result: Option<person::Bot>,
    pub created_at_ms: i64,
}
impl std::fmt::Debug for Record {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("CreationRecord(<redacted>)")
    }
}

#[derive(Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Command {
    Read {
        request: Uuid,
    },
    Pending {
        after: Option<Uuid>,
    },
    Begin {
        request: Uuid,
        bot: Uuid,
        definition: Definition,
        authored: Option<AuthoredRole>,
        seed: Option<Vec<u8>>,
    },
    Advance {
        request: Uuid,
        revision: u64,
        step: Step,
    },
}

#[derive(Clone, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Step {
    StartFolder,
    FolderReady { binding: String },
    StartRole,
    RoleVerified,
    Complete,
    Failed { reason: Failure },
    Retry,
    Abandon,
}

#[derive(Clone, Serialize, Deserialize)]
pub struct Request {
    pub owner: String,
    pub sender: String,
    pub command: Command,
}
impl std::fmt::Debug for Request {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("CreationRequest(<redacted>)")
    }
}
#[derive(Clone, Serialize, Deserialize)]
pub enum Reply {
    Record(Option<Record>),
    Pending(Vec<Record>),
}
impl std::fmt::Debug for Reply {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("CreationReply(<redacted>)")
    }
}
fn encode<T: Serialize>(value: &T) -> Result<Vec<u8>, Error> {
    let bytes = serde_json::to_vec(value).map_err(|_| Error::InvalidRequest)?;
    if bytes.len() > person::MAX_COMMAND_BYTES {
        return Err(Error::InputTooSmall);
    }
    Ok(bytes)
}
fn read(c: &Connection, owner: &str, request: Uuid) -> Result<Option<Record>, Error> {
    let row: Option<Vec<u8>> = c
        .query_row(
            "SELECT record FROM creations WHERE owner=?1 AND request=?2",
            params![owner, request.to_string()],
            |r| r.get(0),
        )
        .optional()?;
    row.map(|bytes| serde_json::from_slice(&bytes).map_err(|_| Error::StorageUnavailable))
        .transpose()
}
fn save(c: &Connection, owner: &str, record: &Record) -> Result<(), Error> {
    c.execute(
        "UPDATE creations SET record=?3,terminal=?4 WHERE owner=?1 AND request=?2",
        params![
            owner,
            record.request.to_string(),
            encode(record)?,
            record.phase.terminal()
        ],
    )?;
    Ok(())
}

pub fn handle(db: &mut Database, request: Request, now: i64) -> Result<Reply, Error> {
    // The private IPC endpoint authenticates before this entry point.
    if request.owner.is_empty()
        || request.sender.is_empty()
        || request.owner.len() > 256
        || request.sender.len() > 256
        || now < 0
    {
        return Err(Error::InvalidRequest);
    }
    encode(&request)?;
    let who = Person {
        owner: request.owner,
        sender: request.sender,
    };
    match request.command {
        Command::Read { request } => Ok(Reply::Record(read(&db.connection, &who.owner, request)?)),
        Command::Pending { after } => {
            let mut statement = db.connection.prepare("SELECT record FROM creations WHERE owner=?1 AND terminal=0 AND request>?2 ORDER BY request LIMIT 32")?;
            let rows = statement.query_map(
                params![
                    who.owner,
                    after.map(|id| id.to_string()).unwrap_or_default()
                ],
                |r| r.get::<_, Vec<u8>>(0),
            )?;
            let mut out = vec![];
            let mut size = 0;
            for bytes in rows {
                let mut record: Record =
                    serde_json::from_slice(&bytes?).map_err(|_| Error::StorageUnavailable)?;
                // Listings carry enough to reopen a creation, never its seed.
                if let Some(seed) = record.seed.as_mut() {
                    seed.bytes.clear();
                }
                size += encode(&record)?.len();
                if size > person::MAX_COMMAND_BYTES {
                    break;
                }
                out.push(record);
            }
            Ok(Reply::Pending(out))
        }
        Command::Begin {
            request,
            bot,
            definition,
            authored,
            seed,
        } => {
            if request.is_nil() || bot.is_nil() {
                return Err(Error::InvalidRequest);
            }
            person::change::validate_definition(&definition)?;
            let digest =
                crate::messages::receipts::digest("creation", &(bot, &definition, &authored))?;
            let tx = db.connection.transaction()?;
            let prior: Option<Vec<u8>> = tx
                .query_row(
                    "SELECT digest FROM creations WHERE owner=?1 AND request=?2",
                    params![who.owner, request.to_string()],
                    |r| r.get(0),
                )
                .optional()?;
            if let Some(prior) = prior {
                if prior != digest {
                    return Err(Error::Conflict);
                }
                return Ok(Reply::Record(read(&tx, &who.owner, request)?));
            }
            let exists: bool = tx.query_row("SELECT EXISTS(SELECT 1 FROM bots WHERE id=?1) OR EXISTS(SELECT 1 FROM creations WHERE bot=?1)",[bot.to_string()], |r|r.get(0))?;
            if exists {
                return Err(Error::Conflict);
            }
            let full: bool = tx.query_row("SELECT (SELECT COUNT(*) FROM creations WHERE terminal=0)>=256 OR (SELECT COUNT(*) FROM creations WHERE terminal=0 AND owner=?1)>=64",[&who.owner],|r|r.get(0))?;
            if full {
                return Err(Error::EngineUnavailable);
            }
            let mut definition = definition;
            let seed = match (authored, seed) {
                (Some(role), Some(bytes))
                    if definition.role.is_none()
                        && !bytes.is_empty()
                        && !role.title.trim().is_empty()
                        && role.title.chars().count() <= 256
                        && role.markdown.len() <= 128 * 1024 =>
                {
                    let candidate = Uuid::new_v4();
                    definition.role = Some(candidate);
                    Some(Seed {
                        candidate,
                        request: Uuid::new_v4(),
                        title: role.title,
                        hash: blake3::hash(&bytes).to_hex().to_string(),
                        bytes,
                    })
                }
                (None, None) => None,
                _ => return Err(Error::InvalidRequest),
            };
            let record = Record {
                request,
                bot,
                revision: 1,
                definition,
                seed,
                phase: Phase::Intent,
                failure: None,
                folder_binding: None,
                result: None,
                created_at_ms: now,
            };
            // Leave room for the folder binding and completed Bot projection.
            if encode(&record)?.len() + encode(&record.definition)?.len() + 16 * 1024
                > person::MAX_COMMAND_BYTES
            {
                return Err(Error::InputTooSmall);
            }
            tx.execute(
                "INSERT INTO creations(request,owner,bot,digest,record) VALUES (?1,?2,?3,?4,?5)",
                params![
                    request.to_string(),
                    who.owner,
                    bot.to_string(),
                    digest,
                    encode(&record)?
                ],
            )?;
            tx.commit()?;
            Ok(Reply::Record(Some(record)))
        }
        Command::Advance {
            request,
            revision,
            step,
        } => {
            let tx = db.connection.transaction()?;
            let mut record = read(&tx, &who.owner, request)?.ok_or(Error::NotAllowed)?;
            if record.revision != revision {
                return Err(Error::Conflict);
            }
            if record.phase.terminal() {
                return Err(Error::NotAllowed);
            }
            if record.failure.is_some()
                && !matches!(step, Step::Retry | Step::Abandon | Step::Failed { .. })
            {
                return Err(Error::NotAllowed);
            }
            match step {
                Step::StartFolder if record.phase == Phase::Intent => {
                    record.phase = Phase::FolderPending
                }
                Step::FolderReady { binding } if record.phase == Phase::FolderPending => {
                    if binding.len() > 4096
                        || binding.contains('\0')
                        || !std::path::Path::new(&binding).is_absolute()
                    {
                        return Err(Error::InvalidRequest);
                    }
                    record.folder_binding = Some(binding);
                    record.phase = if record.seed.is_some() {
                        Phase::FolderReady
                    } else {
                        Phase::Ready
                    };
                }
                Step::StartRole if record.phase == Phase::FolderReady => {
                    record.phase = Phase::RolePending
                }
                Step::RoleVerified if record.phase == Phase::RolePending => {
                    record.phase = Phase::Ready
                }
                Step::Complete if record.phase == Phase::Ready => {
                    let result =
                        person::change::create(&tx, &who, record.bot, &record.definition, now)?;
                    record.result = Some(
                        serde_json::from_value(result).map_err(|_| Error::StorageUnavailable)?,
                    );
                    record.phase = Phase::Completed;
                }
                Step::Failed { reason } => record.failure = Some(reason),
                Step::Retry => record.failure = None,
                Step::Abandon => record.phase = Phase::Abandoned,
                _ => return Err(Error::NotAllowed),
            }
            record.revision = record.revision.checked_add(1).ok_or(Error::Conflict)?;
            // Terminal creations cannot run the effect again. Keep its
            // identities/hash for provenance, not a second copy of Role text.
            if record.phase.terminal() {
                if let Some(seed) = record.seed.as_mut() {
                    seed.bytes.clear();
                }
            }
            save(&tx, &who.owner, &record)?;
            tx.commit()?;
            Ok(Reply::Record(Some(record)))
        }
    }
}

